 @AfterEach void cleanup(){if(service!=null)service.close();if(admin!=null&&schema!=null)admin.execute("drop schema "+schema+" cascade");}
 UUID initialize(String name,long size){return UUID.fromString(text(tx.execute(s->transfers.initialize(91L,Map.of("fileName",name,"fileSize",size,"requestId",UUID.randomUUID().toString()))).get("id")));}
 String hash(byte[] bytes){return PartnerFileWorkspace.digest(new ByteArrayInputStream(bytes));}
 void part(UUID id,long index,byte[] bytes){tx.execute(s->transfers.part(91L,id,index,hash(bytes),new ByteArrayInputStream(bytes)));}
 long complete(UUID id){return number(tx.execute(s->transfers.complete(91L,id,Map.of(),null)).get("attachmentId"));}
 long uploaded(Path path) throws Exception {UUID id=initialize("source.xlsx",Files.size(path));try(var in=Files.newInputStream(path)){for(long i=0;;i++){byte[] bytes=in.readNBytes(PartnerSelectionTransfers.CHUNK_SIZE);if(bytes.length==0)break;part(id,i,bytes);}}return complete(id);}
 Map<String,Object> waitingJob() throws Exception {return waitingJob("SUP-XD");}
 Map<String,Object> waitingJob(String sourceSupplier) throws Exception {Path source=temporary.resolve("small.xlsx");String rid=UUID.randomUUID().toString();workbook.write(source,UUID.randomUUID(),7,List.of(new PartnerSelectionWorkbook.ExportSheet("SUP-XD","熊大","XD",List.of(),sink->sink.accept(Map.of("rowId",rid,"rowVersion",0,"name","真实格式QA候选","modelText","iPhone18 Pro Max","sampleQty",2)))),(row,pos)->{});
  // An externally issued file has no PLM export job and must not smuggle a fabricated export identity.
  Path plain=temporary.resolve("plain.xlsx");try(var b=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new ByteArrayInputStream(Files.readAllBytes(source)))){var supplierIdentity=b.getSheetAt(0).getRow(4).getCell(PartnerSelectionWorkbook.HEADERS.size()+PartnerSelectionWorkbook.TECH.indexOf("__supplierCode"));supplierIdentity.setBlank();supplierIdentity.setCellValue(sourceSupplier);var marker=b.getSheetAt(0).getRow(4).getCell(PartnerSelectionWorkbook.HEADERS.size()+2);marker.setBlank();marker.setCellValue("");assertThat(b.getSheetAt(0).getRow(3).getCell(PartnerSelectionWorkbook.HEADERS.size()+2).getStringCellValue()).isEqualTo("__exportJob");try(var out=Files.newOutputStream(plain)){b.write(out);}}
  workbook.parse(plain,Map.of("熊大选品","SUP-XD"),temporary,new PartnerSelectionWorkbook.Sink(){public void row(PartnerSelectionWorkbook.ParsedRow row){assertThat(text(row.values().get("exportJob"))).as("external source export marker").isEmpty();}public void image(PartnerSelectionWorkbook.Image image){}});
  long fid=uploaded(plain);return tx.execute(s->service.createImport(91L,Map.of("attachmentId",fid,"requestId",UUID.randomUUID().toString())));
 }
 Map<String,Object> readyJob() throws Exception {var created=waitingJob();UUID jid=UUID.fromString(text(created.get("id")));tx.execute(s->service.parse(91L,jid,Map.of("sheets",List.of(Map.of("name","熊大选品","supplierCode","SUP-XD","supplierConfirmed",true)))));service.processImport(jdbc.queryForMap("select * from plm_partner_file_job where job_id=?",jid));assertThat(jdbc.queryForList("select action,messages::text from plm_partner_file_job_row where job_id=?",jid)).allSatisfy(r->assertThat(r.get("action")).withFailMessage("%s",r).isNotEqualTo("conflict"));return service.job(91L,jid);
 }
 @Test void resumedChunksAndRepeatedCompletionMakeOneExistingLibraryAttachment(){byte[] first=new byte[PartnerSelectionTransfers.CHUNK_SIZE],last=new byte[]{3,1,4};new Random(17).nextBytes(first);UUID uid=initialize("quote.xlsx",(long)first.length+last.length);part(uid,0,first);assertThat(transfers.status(91L,uid).get("receivedParts")).isEqualTo(List.of(0L));assertThat(transfers.status(91L,uid).get("partHashes")).isEqualTo(Map.of("0",hash(first)));part(uid,0,first);part(uid,1,last);long fid=complete(uid);assertThat(complete(uid)).isEqualTo(fid);assertThat(jdbc.queryForObject("select count(*) from plm_attachment",Long.class)).isEqualTo(1);verify(materials,times(1)).uploadResumable(eq(91L),any(),anyString(),any());}
 @Test void corruptOrDifferentSameIndexDoesNotOverwriteAcceptedChunk(){byte[] data={1,2,3};UUID uid=initialize("quote.xlsx",3);assertThatThrownBy(()->tx.execute(s->transfers.part(91L,uid,0,hash(new byte[]{4,5,6}),new ByteArrayInputStream(data)))).hasMessageContaining("SHA-256");assertThat(jdbc.queryForObject("select count(*) from plm_partner_upload_part",Long.class)).isZero();part(uid,0,data);assertThatThrownBy(()->part(uid,0,new byte[]{3,2,1})).hasMessageContaining("内容不同");assertThat(PartnerFileWorkspace.checksum(workspace.part(uid,0))).isEqualTo(hash(data));}
 @Test void completionRequiresEveryChunkAndWrongWholeHashRetainsResumableParts(){UUID uid=initialize("quote.xlsx",3);assertThatThrownBy(()->complete(uid)).hasMessageContaining("缺失");part(uid,0,new byte[]{1,2,3});assertThatThrownBy(()->tx.execute(s->transfers.complete(91L,uid,Map.of("sha256",hash(new byte[]{4})),null))).hasMessageContaining("完整文件");assertThat(jdbc.queryForObject("select count(*) from plm_attachment",Long.class)).isZero();assertThat(workspace.part(uid,0)).exists();}
 @Test void stagedPreviewIsDurablePagedAndPublicationRetryNeverDuplicates() throws Exception {var job=readyJob();UUID jid=UUID.fromString(text(job.get("id")));assertThat(job.get("status")).isEqualTo("ready");assertThat(service.rows(91,jid,Map.of("size","1")).get("totalElements")).isEqualTo(1L);assertThat(jdbc.queryForObject("select count(*) from qa_published",Long.class)).isZero();var first=tx.execute(s->service.commit(91,jid,Map.of()));var again=tx.execute(s->service.commit(91,jid,Map.of()));assertThat(number(again.get("id"))).isEqualTo(number(first.get("id")));assertThat(jdbc.queryForObject("select count(*) from qa_published",Long.class)).isEqualTo(1);verify(selections,times(1)).applyImportedRows(anyLong(),anyLong(),anyString(),any());}
 @Test void failedAtomicPublicationRollsBackStagedResultAndBusinessWrites() throws Exception {var job=readyJob();UUID jid=UUID.fromString(text(job.get("id")));when(selections.applyImportedRows(eq(91L),anyLong(),anyString(),any())).thenAnswer(i->{jdbc.update("insert into qa_published values('rollback','{}')");throw invalid("强制审计失败");});assertThatThrownBy(()->tx.execute(s->service.commit(91,jid,Map.of()))).hasMessageContaining("审计失败");assertThat(jdbc.queryForObject("select count(*) from qa_published",Long.class)).isZero();assertThat(service.job(91,jid).get("status")).isEqualTo("ready");}
 @Test void uploadAndTaskOwnershipAreRecheckedBeforeReadingDurableEvidence() throws Exception {UUID uid=initialize("quote.xlsx",3);var job=readyJob();when(pilot.actorId()).thenReturn(2L);assertThatThrownBy(()->transfers.status(91,uid)).hasMessageContaining("不属于当前账号");assertThatThrownBy(()->service.job(91,UUID.fromString(text(job.get("id"))))).hasMessageContaining("不属于当前账号");}
 @Test void staleBaseCannotPublishAndUnselectedRowsRemainOnlyInStaging() throws Exception {var job=readyJob();UUID jid=UUID.fromString(text(job.get("id")));head.put("version",8L);assertThatThrownBy(()->tx.execute(s->service.commit(91,jid,Map.of()))).hasMessageContaining("已变化");assertThat(jdbc.queryForObject("select count(*) from qa_published",Long.class)).isZero();}
 @Test void unfinishedTransferCanBeCancelledWithoutDeletingACompletedAttachment(){UUID uid=initialize("quote.xlsx",3);part(uid,0,new byte[]{1,2,3});tx.execute(s->{transfers.cancel(91,uid);return null;});assertThat(transfers.status(91,uid).get("status")).isEqualTo("cancelled");assertThat(workspace.part(uid,0)).doesNotExist();UUID done=initialize("done.xlsx",3);part(done,0,new byte[]{4,5,6});complete(done);assertThatThrownBy(()->tx.execute(s->{transfers.cancel(91,done);return null;})).hasMessageContaining("正式附件");}
