  assertThat(queued.get("status")).isEqualTo("queued");var witness=maps(queued.get("selectedSheets"));assertThat(witness).singleElement().satisfies(page->{assertThat(page).containsEntry("name","熊大选品").containsEntry("supplierCode","SUP-XD").containsEntry("supplierConfirmed",true).containsEntry("confirmedBy","qa");assertThat(java.time.Instant.parse(text(page.get("confirmedAt")))).isNotNull();});assertThat(maps(service.job(91,jid).get("selectedSheets"))).isEqualTo(witness);
