 @Test void realXiongdaStageCorrectionCommitAndExcelRoundTripKeepExactOriginalQuoteEvidenceAndAllPictures() throws Exception {
  String configured=System.getProperty("plm.selection.xiongda.workbook","");Assumptions.assumeTrue(!configured.isBlank());Path originalFile=Path.of(configured);String sourceHash=PartnerFileWorkspace.checksum(originalFile);useSupplierQuote();service.close();jdbc.execute("alter table plm_attachment add column file_size bigint");var permissions=mock(PartnerOperationsAccess.class);when(permissions.costs()).thenReturn(true);when(permissions.engineering()).thenReturn(true);var profiles=mock(SupplierProfileService.class);doCallRealMethod().when(profiles).requireSupplierForNewUse(anyString());when(profiles.requireSupplier(anyString())).thenReturn(Map.of("supplierName","熊大","supplierCode","SUP-XD","status","active"));var realSelections=new PartnerSelectionService(store,permissions,profiles,mock(PartnerProductService.class),materials);quotes=new PartnerQuoteLines(store,permissions,realSelections);var ranges=mock(SupplierRangeService.class);when(ranges.ranges(anyString(),anyMap())).thenReturn(Map.of("content",List.of(),"totalElements",0));service=new PartnerSelectionImportService(store,realSelections,workbook,workspace,materials,ranges,profiles,tx.getTransactionManager(),quotes,new PartnerFileSourceAccess(store,permissions));
  long fid=uploaded(originalFile);var waiting=tx.execute(s->service.createImport(91,Map.of("attachmentId",fid,"requestId","real-xiongda")));UUID jid=UUID.fromString(text(waiting.get("id")));tx.execute(s->service.parse(91,jid,Map.of("sheets",List.of(Map.of("name","熊大选品","supplierCode","SUP-XD","supplierConfirmed",true)))));service.processImport(jdbc.queryForMap("select * from plm_partner_file_job where job_id=?",jid));assertThat(service.job(91,jid).get("status")).isEqualTo("ready");assertThat(jdbc.queryForObject("select count(*) from plm_partner_file_job_row where job_id=?",Long.class,jid)).isEqualTo(19);assertThat(jdbc.queryForObject("select count(*) from plm_partner_file_job_image where job_id=?",Long.class,jid)).isEqualTo(28);var stage=maps(service.rows(91,jid,Map.of()).get("content")).get(0);var before=map(stage.get("values"));assertThat(before).containsEntry("currency","CNY").containsEntry("currencySource","business_default");assertThat(map(before.get("rawQuoteFields"))).containsEntry("currency","");
  var corrected=tx.execute(s->service.correct(91,jid,UUID.fromString(text(stage.get("rowId"))),Map.of("version",stage.get("version"),"values",Map.of("notes","仅核对非金额资料","currencySource","explicit","rawQuoteFields",Map.of("currency","EUR")))));assertThat(map(corrected.get("values"))).containsEntry("currencySource","business_default");assertThat(map(map(corrected.get("values")).get("rawQuoteFields"))).isEqualTo(map(before.get("rawQuoteFields")));tx.execute(s->service.commit(91,jid,Map.of()));assertThat(jdbc.queryForObject("select count(*) from plm_partner_quote_line",Long.class)).isEqualTo(19);
  for(var joined:jdbc.queryForList("select s.data::text as staged,q.data::text as published from plm_partner_file_job_row s join plm_partner_quote_line q on q.line_id=s.row_id where s.job_id=?",jid)){var staged=decode(json,joined.get("staged"));var published=decode(json,joined.get("published"));assertThat(published).containsEntry("currency","CNY").containsEntry("currencySource","business_default");assertThat(published.get("rawQuoteFields")).isEqualTo(staged.get("rawQuoteFields"));assertThat(published.get("moqSource")).isEqualTo(staged.get("moqSource"));}long attachments=jdbc.queryForObject("select count(*) from plm_attachment",Long.class);
  var export=tx.execute(s->service.createExport(91,Map.of("requestId","real-export")));UUID eid=UUID.fromString(text(export.get("id")));service.processExport(jdbc.queryForMap("select * from plm_partner_file_job where job_id=?",eid));assertThat(service.job(91,eid).get("status")).isEqualTo("ready");var parsedRows=new ArrayList<PartnerSelectionWorkbook.ParsedRow>();var pictures=new ArrayList<PartnerSelectionWorkbook.Image>();workbook.parse(service.download(91,eid),Map.of("熊大选品","SUP-XD"),temporary,new PartnerSelectionWorkbook.Sink(){public void row(PartnerSelectionWorkbook.ParsedRow row){parsedRows.add(row);}public void image(PartnerSelectionWorkbook.Image image){pictures.add(image);}});assertThat(parsedRows).hasSize(19);assertThat(pictures).hasSize(28);assertThat(parsedRows).allSatisfy(row->{assertThat(row.values()).containsEntry("currencySource","business_default");assertThat(map(row.values().get("rawQuoteFields"))).containsEntry("currency","");});assertThat(jdbc.queryForObject("select count(*) from plm_attachment",Long.class)).isEqualTo(attachments);assertThat(PartnerFileWorkspace.checksum(originalFile)).isEqualTo(sourceHash);assertThat(jdbc.queryForObject("select count(*) from plm_partner_record",Long.class)).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from qa_published",Long.class)).isZero();
 }
